<?php

namespace Database\Seeders;

use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\DB;

class VisitaCarcelCatalogSeeder extends Seeder
{
    public function run(): void
    {
        $catalog = json_decode(gzdecode(base64_decode('')), true);

        DB::table('visita_carcel_causas')->insertOrIgnore($catalog['causas']);

        $causaIds = DB::table('visita_carcel_causas')
            ->whereIn('ruc', array_column($catalog['causas'], 'ruc'))
            ->whereNull('deleted_at')
            ->pluck('id', 'ruc');

        $seen = [];

        foreach ($catalog['imputados'] as $imputado) {
            $ruc = $imputado['ruc'];
            unset($imputado['ruc']);
            $imputado['visita_carcel_causa_id'] = $causaIds[$ruc];
            $signature = json_encode($imputado);
            $seen[$signature] = ($seen[$signature] ?? 0) + 1;

            if (DB::table('visita_carcel_imputados')->where($imputado)->whereNull('deleted_at')->count() < $seen[$signature]) {
                DB::table('visita_carcel_imputados')->insert($imputado);
            }
        }
    }

    public function expectedCausasCount(): int
    {
        return 113;
    }

    public function expectedImputadosCount(): int
    {
        return 207;
    }
}
